function EGF_COEFFS(a, N):
    for n in 0..N-1:
        c[n] <- a[n] / factorial(n)
    return c

function SEQ_OF(c, N):          # inverse
    for n in 0..N-1:
        a[n] <- factorial(n) * c[n]
    return a
# SEQ_OF(EGF_COEFFS(a)) = a   and   EGF_COEFFS(SEQ_OF(c)) = c

function BIN_CONV(a, b, N):
    for n in 0..N-1:
        s <- 0
        for i in 0..n:
            s <- s + C(n,i) * a[i] * b[n-i]
        out[n] <- s
    return out

function CAUCHY(f, g, N):        # product of EGFs
    for n in 0..N-1:
        out[n] <- sum_{i=0}^{n} f[i]*g[n-i]
    return out
# EGF_COEFFS(BIN_CONV(a,b)) == CAUCHY(EGF_COEFFS(a), EGF_COEFFS(b))

