from fractions import Fraction
from math import comb
from typing import Callable, List

Seq = Callable[[int], Fraction]

def bin_conv(a: Seq, b: Seq, order: int) -> List[Fraction]:
    """Binomial (exponential) convolution (a*b)_n = sum_{i+j=n} C(n,i) a_i b_j,
    the counting sequence of the Day-convolution product of species."""
    out: List[Fraction] = []
    for n in range(order):
        out.append(sum((Fraction(comb(n, i)) * a(i) * b(n - i)
                        for i in range(n + 1)), Fraction(0)))
    return out

def cauchy_product(f: List[Fraction], g: List[Fraction], order: int) -> List[Fraction]:
    """Ordinary power-series product; equals EGF of the binomial convolution."""
    return [sum((f[i] * g[n - i] for i in range(n + 1)), Fraction(0))
            for n in range(order)]

from fractions import Fraction
from typing import Callable, List

Seq = Callable[[int], Fraction]

def seq_deriv(a: Seq) -> Seq:
    """Derivative species: (F')_n = a_{n+1} (adjoin a ghost label)."""
    return lambda n: a(n + 1)

def seq_point(a: Seq) -> Seq:
    """Pointed species: (F^.)_n = n * a_n (mark a special label)."""
    return lambda n: Fraction(n) * a(n)

def derivative_series(f: List[Fraction]) -> List[Fraction]:
    """Formal derivative d/dX: [X^n] f' = (n+1) [X^{n+1}] f. Equals EGF(seq_deriv a)."""
    return [Fraction(n + 1) * f[n + 1] for n in range(len(f) - 1)]

from fractions import Fraction
from math import comb
from typing import Callable, List

Seq = Callable[[int], Fraction]

def _conv(a: Seq, b: Seq, n: int) -> Fraction:
    return sum((Fraction(comb(n, i)) * a(i) * b(n - i) for i in range(n + 1)),
               Fraction(0))

def leibniz_check(a: Seq, b: Seq, order: int) -> bool:
    """Verify the structural product rule (a*b)' = a'*b + a*b' coefficientwise.
    Returns True iff the identity holds up to the given order."""
    da, db = (lambda n: a(n + 1)), (lambda n: b(n + 1))
    for n in range(order):
        lhs = _conv(a, b, n + 1)                 # (a*b)'_n = (a*b)_{n+1}
        rhs = _conv(da, b, n) + _conv(a, db, n)  # (a'*b + a*b')_n
        if lhs != rhs:
            return False
    return True
